class OrderService {
  process(order: Order) {
    let total = 0;
    for (const item of order.items) {
      total += item.price * item.quantity;
    }
    if (order.coupon) total *= 0.9;
    DB.save(order);
    Email.sendReceipt(order);
  }
}

